<?php
/**
 * Icon index and texts for the icon picker as JSON (developer docs, chapter 08 (Components and extensions)) - called from
 * iconpicker.ext.js: backendExtensions/IconPicker/index.php; the session is
 * checked by Backend::backendPath().
 *
 * Source is data/reduced-index.json (generated by tools/reduce-search-index.py from
 * the search index of the Google Material Icons website). Response:
 *     texts       snippets ext.iconpicker.* for the UI (language of the administrator)
 *     categories  [{name, label}] in the order of the index, label from
 *                 ext.iconpicker.category_{name} (if the snippet is missing: the name)
 *     icons       [{name, categories, tags}] as in the index
 */
// @var Camindo\Core\ContainerInterface $app
use Camindo\Core\Cms;

$cms = $app->get(Cms::class);
$file = dirname(__DIR__) . '/data/reduced-index.json';
$index = is_file($file) ? json_decode((string)file_get_contents($file), true) : null;
if (!is_array($index) || !isset($index['icons'])) {
    http_response_code(500);
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode(['error' => $cms->snippet('ext.iconpicker.error_load')]);
    exit;
}

$categories = [];
foreach ($index['icons'] as $icon) {
    foreach ((array)($icon['categories'] ?? []) as $category) {
        $category = (string)$category;
        if (isset($categories[$category])) continue;
        $snippetId = 'ext.iconpicker.category_' . preg_replace('/[^a-z0-9_]/', '_', strtolower($category));
        $label = $cms->snippet($snippetId);
        $categories[$category] = ['name' => $category, 'label' => $label === $snippetId ? $category : $label];
    }
}
ksort($categories);

$texts = [];
foreach (['speak_open', 'speak_close', 'speak_prev', 'speak_next', 'placeholder_search', 'label_results', 'label_no_results', 'label_none'] as $key) {
    $texts[$key] = $cms->snippet('ext.iconpicker.' . $key);
}

header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: private, max-age=3600');
echo json_encode([
    'texts'      => $texts,
    'categories' => array_values($categories),
    'icons'      => $index['icons'],
], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
exit;
